import { View, Text, StyleSheet } from "react-native";
import { registerRootComponent } from "expo";

function App() {
  return (
    <View style={styles.card}>
      <Text nativeID="badge" style={styles.badge}>ШИНЭ</Text>
      <View style={styles.cover} />
      {/* энд бичнэ үү: badge-г бүрхүүлийн дээр гарга */}
    </View>
  );
}

const styles = StyleSheet.create({
  card: { margin: 24, width: 200, height: 160 },
  badge: { position: "absolute", top: 12, left: 12, backgroundColor: "#16a34a", color: "#fff", fontWeight: "bold", padding: 8, borderRadius: 8 },
  cover: { position: "absolute", inset: 0, backgroundColor: "#334155", borderRadius: 16 },
});

registerRootComponent(App);

